import subprocess
import sys

class Installer:
    def __init__(self):
        self.packages = {
            'pip': 'pip',
            'flask': 'flask',
        }

    def _run_pip(self, *args):
        subprocess.check_call([sys.executable, "-m", "pip"] + list(args))

    def _install(self, package):
        self._run_pip('install', package)

    def _is_available(self, module_name):
        try:
            __import__(module_name)
            return True
        except ImportError:
            return False

    def ensure(self):
        for pkg, mod in self.packages.items():
            if not self._is_available(mod):
                print(f"{mod} not found, installing {pkg}...")
                self._install(pkg)
            else:
                print(f"{mod} is already installed")

def main():
    installer = Installer()
    installer.ensure()

if __name__ == '__main__':
    main()

"""
HTTP Basic Auth decorator with configurable credential key.
"""

from functools import wraps

from flask import request, jsonify, current_app
import flask_tasks


def _error_response(message, status):
    """Create a JSON response with given message and HTTP status."""
    resp = jsonify({'message': message, 'statusCode': status})
    resp.status_code = status
    return resp


def basic_auth(config_key='basic_auth_credentials'):
    """
    Decorator that checks request.authorization against the credentials
    stored under the given config key in current_app.config.
    """

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            try:
                cred_dict = current_app.config[config_key]
                required = (cred_dict['username'], cred_dict['password'])
            except KeyError:
                return _error_response('Server credential store setup incomplete.', 500)

            try:
                provided = (request.authorization.username,
                             request.authorization.password)
            except AttributeError:
                resp = _error_response('HTTP Basic Auth required for this URL.', 401)
                resp.headers['WWW-Authenticate'] = 'Basic'
                return resp

            if provided != required:
                resp = _error_response(
                    'Could not verify your access level for that URL. You have to login with proper credentials',
                    401)
                resp.headers['WWW-Authenticate'] = 'Basic'
                return resp

            return func(*args, **kwargs)

        return wrapper

    return decorator

