def _pagination_context(page, page_size):
    page = int(page)
    if page is None or page <= 0:
        return {"next_page": 0, "prev_page": 1, "current": True}
    return {"next_page": page - 1, "prev_page": page + 1, "current": False}


def _load_posts(page, page_size=3):
    return get_page(page_size, page)


def register_routes(bp):
    @bp.route("/blog/<page>/", methods=["GET"])
    def blog_page(page=None):
        ctx = _pagination_context(page, 3)
        posts = _load_posts(page, 3)
        return render_extensions(
            "blog/blog_page.html",
            posts=posts,
            **ctx,
        )

    @bp.route("/post_detail/<pk>/", methods=["GET"])
    def blog_detail(pk):
        post = get_post_detail(int(pk))
        return render_extensions("blog/blog_detail.html", post=post)


register_routes(blog_bp)

app = Flask(__name__)
app.register_blueprint(blog_bp)

