from MyConfig import MyConfig
from Utilities import debug_msg


class SingletonMeta(type):
    _instances = {}

    def __call__(cls, *args, **kwargs):
        if cls not in cls._instances:
            cls._instances[cls] = super().__call__(*args, **kwargs)
        return cls._instances[cls]


class Initialization(metaclass=SingletonMeta):
    _app: Flask | None = None
    _db: SQLAlchemy | None = None
    _config = MyConfig()

    def _build_database_uri(self, db_path: str | None) -> str:
        base_dir = os.path.abspath(os.path.dirname(__file__))
        if db_path is None:
            uri = f"sqlite:///{os.path.join(base_dir, self._config.getConfig('database_path'))}"
        else:
            uri = f"sqlite:///{os.path.join(base_dir, db_path)}"
        return uri

    def global_create_app(self, name: str | None, db_path: str | None) -> Flask:
        if name is None:
            debug_msg("Warning: no app name!")
            name = '__main__'

        self._app = Flask(name)
        db_uri = self._build_database_uri(db_path)
        debug_msg(f"----database_path---: {db_uri}")
        self._app.config['SQLALCHEMY_DATABASE_URI'] = db_uri
        debug_msg(self._app.config['SQLALCHEMY_DATABASE_URI'])
        self._app.config['SQLALCHEMY_COMMIT_ON_TEARDOWN'] = True
        return self._app

    def global_create_db(self, app: Flask | None = None) -> SQLAlchemy:
        if app is None:
            app = self._app
        self._db = SQLAlchemy(app)
        return self._db

    def get_global_app(self) -> Flask | None:
        return self._app

