import os
import requests
from flask import Flask, request, jsonify
import flask_tasks
from sqlalchemy import create_engine, text

app = Flask(__name__)

DATABASE_URL = os.getenv('DATABASE_URL', 'postgresql://postgres:example@db:5432/postgres')
engine = create_engine(DATABASE_URL)

MICROSERVICES = {
    'user': 'http://user-service:5001',
    'order': 'http://order-service:5002',
    'inventory': 'http://inventory-service:5003',
    'payment': 'http://payment-service:5004',
    'shipping': 'http://shipping-service:5005',
}

def forward_request(service_name):
    base = MICROSERVICES[service_name]
    path = request.full_path.lstrip('/api').lstrip('/')
    url = f"{base}/{path}"
    try:
        proxied = requests.request(
            method=request.method,
            url=url,
            headers=request.headers,
            data=request.get_data(),
            params=request.args,
            timeout=5
        )
        return (proxied.content, proxied.status_code, proxied.headers.items())
    except requests.RequestException as exc:
        return jsonify({'error': str(exc)}), 502

@app.route('/api/<service>', methods=['GET', 'POST', 'PUT', 'DELETE'])
def api_gateway(service):
    if service not in MICROSERVICES:
        return jsonify({'error': 'Service not found'}), 404
    return forward_request(service)

@app.route('/status')
def db_status():
    try:
        with engine.begin() as conn:
            conn.execute(text('SELECT 1'))
        return jsonify({'database': 'available'}), 200
    except Exception as err:
        return jsonify({'database': 'unreachable', 'detail': str(err)}), 500

@app.route('/data')
def data_endpoint():
    try:
        with engine.begin() as conn:
            rows = conn.execute(text('SELECT * FROM sample_table LIMIT 5')).fetchall()
        return jsonify([dict(row) for row in rows]), 200
    except Exception as err:
        return jsonify({'error': str(err)}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)

