@app.route('/merge-sort-array', methods=['POST'])
def merge_and_sort_array():
    data = request.get_json()
    if 'arrays' not in data:
        return jsonify({"error": "Missing 'arrays' in request data"})
    arrays = data['arrays']
    if not all(isinstance(arr, list) for arr in arrays):
        return jsonify({"error": "'arrays' field should be a list of lists"})
    merged = [num for sublist in arrays for num in sublist]
    merged.sort()
    return jsonify(merged)

