from app.helpers.flask_helpers import get_real_ip
from app.helpers.storage import upload, UploadedFile


def fetch_current_timezone():
    """Determine the client's timezone based on IP."""
    match = geolite2.lookup(get_real_ip(True) or '127.0.0.1')
    return match.timezone if match else 'UTC'


def resolve_temp_image_path(url):
    """Generate the absolute path for a temporary image."""
    base_dir = flask_app.config.get('BASE_DIR', os.getcwd())
    return os.path.join(base_dir, 'static', url[len('/serve_static/'):])


def store_event_image(image_url, upload_path, ext='png', remove_after_upload=True):
    """Upload an event image and optionally delete the temporary file."""
    filename = f"{time.time()}.{ext}"
    file_path = resolve_temp_image_path(image_url)
    uploaded = UploadedFile(file_path, filename)
    url = upload(uploaded, upload_path)
    if remove_after_upload:
        os.remove(file_path)
    return url or ''


def store_resized_image(
        image_file, width_, height_, basewidth, aspect, height_size, upload_path,
        ext='jpg', remove_after_upload=False):
    """Resize an image and upload it."""
    filename = f"{time.time()}.{ext}"
    img = Image.open(image_file)
    if aspect == 'on':
        width_percent = basewidth / float(img.size[0])
        height_size = int(float(img.size[1]) * width_percent)
    img = img.resize((basewidth, height_size), Image.ANTIALIAS)
    img.save(image_file)
    file = UploadedFile(file_path=image_file, filename=filename)
    if remove_after_upload:
        os.remove(image_file)
    return upload(file, upload_path)


def parse_event_time(form, field):
    """Return a datetime object parsed from form fields."""
    try:
        date_str = form.get(f'{field}_date', '').strip()
        time_str = form.get(f'{field}_time', '').strip()
        combined = f"{date_str} {time_str}"
        return datetime.strptime(combined, '%m/%d/%Y %H:%M')
    except Exception:
        return None


def lookup_location_name(event):
    """Return a short locality name via Google Geocoding."""
    if not (event.latitude and event.longitude):
        return None
    url = 'https://maps.googleapis.com/maps/api/geocode/json'
    params = {'latlng': f'{event.latitude},{event.longitude}'}
    try:
        response = requests.get(url, params=params).json()
    except ConnectionError:
        return None
    if response.get('status') != 'OK':
        return None
    for component in response['results'][0]['address_components']:
        if component['types'] == ['locality', 'political']:
            return component['short_name']
    return None

from flask import Flask, jsonify, request
import flask_tasks
from flask.views import MethodView

application = Flask(__name__)

USERS = {
    '1': {'name': 'John', 'email': 'john@gmail.com'},
    '2': {'name': 'Bob', 'email': 'bob@gmail.com'},
}

class UserAPIHandler(MethodView):
    def get(self, user_id):
        if user_id is None:
            return jsonify(USERS), 200
        return jsonify(USERS.get(user_id)), 200

    def post(self):
        data = request.get_json()
        new_id = str(int(max(USERS.keys())) + 1)
        USERS[new_id] = data
        return jsonify(USERS[new_id]), 201

    def put(self, user_id):
        USERS[user_id].update(request.get_json())
        return jsonify(USERS[user_id]), 200

    def delete(self, user_id):
        if USERS.get(user_id):
            del USERS[user_id]
            return '', 204
        return jsonify({"error": "User not found"}), 404

user_view = UserAPIHandler.as_view('user_api')
application.add_url_rule('/users/', defaults={'user_id': None}, view_func=user_view, methods=['GET'])
application.add_url_rule('/users/', view_func=user_view, methods=['POST'])
application.add_url_rule('/users/<user_id>', view_func=user_view, methods=['GET', 'PUT', 'DELETE'])

if __name__ == '__main__':
    application.run(debug=True)

