from superdesk.utils import ListCursor

class ClientConfigResource(superdesk.Resource):
    item_methods = []
    public_methods = ['GET']
    resource_methods = ['GET']

class ClientConfigService(superdesk.Service):
    def get(self, req, lookup):
        return ListCursor()

    def on_fetched(self, docs):
        docs['config'] = getattr(self.app, 'client_config', {})

def create_app(config=None):
    app = Flask(__name__)
    if config:
        app.config.update(config)

    app.client_config = {}
    superdesk.register_resource(
        'client_config',
        ClientConfigResource,
        ClientConfigService,
        _app=app
    )
    app.client_config.update({
        'schema': app.config.get('SCHEMA'),
        'editor': app.config.get('EDITOR'),
        'feedback_url': app.config.get('FEEDBACK_URL'),
        'override_ednote_for_corrections': app.config.get(
            'OVERRIDE_EDNOTE_FOR_CORRECTIONS', True
        ),
        'override_ednote_template': app.config.get('OVERRIDE_EDNOTE_TEMPLATE'),
        'default_genre': app.config.get(
            'DEFAULT_GENRE_VALUE_FOR_MANUAL_ARTICLES'
        ),
        'japanese_characters_per_minute': app.config.get(
            'JAPANESE_CHARACTERS_PER_MINUTE'
        ),
        'validator_media_metadata': app.config.get(
            'VALIDATOR_MEDIA_METADATA', {}
        ),
        'publish_content_expiry_minutes': app.config.get(
            'PUBLISHED_CONTENT_EXPIRY_MINUTES', 0
        ),
    })
    return app

