# Set up static routing for addons
ADDON_BASE_PATH = os.path.abspath('website/addons')

@application.route('/static/addons/<addon>/<path:filename>')
def serve_addon_static(addon, filename):
    addon_static_path = os.path.join(ADDON_BASE_PATH, addon, 'static')
    return send_from_directory(addon_static_path, filename)


def register_handler(application, handler_name, func, key=None):
    """Add handler to Flask application if handler has not already been added."""
    handler_adder = getattr(application, handler_name)
    handler_funcs_name = f'{handler_name}_funcs'
    handler_funcs = getattr(application, handler_funcs_name)
    if func not in handler_funcs.get(key, []):
        handler_adder(func)


def register_handlers(application, handlers, key=None):
    """Add multiple handlers to application."""
    for handler_name, func in handlers.iteritems():
        register_handler(application, handler_name, func, key=key)


def custom_redirect(location, code=302):
    """Redirect the client to a desired location, preserving the `view_only` query parameter."""
    view_only = request.args.get('view_only', '')
    if view_only:
        url = furl.furl(location)
        url.args['view_only'] = view_only
        location = url.url
    return flask_redirect(location, code=code)

