from flask import g
import flask_tasks
from meerkat_libs.auth_client import Authorise as libs_auth
from .app import application
from .messages import messages


class CustomAuthorise(libs_auth):
    """
    Extension of the meerkat_libs auth_client Authorise class.
    Overrides check_auth to add location‑based access control.
    """

    def check_auth(self, access, countries, logic='OR'):
        libs_auth.check_auth(self, access, countries, logic)

        allowed_location = 9999
        for level, loc in application.config.get('LOCATION_AUTH', {}).items():
            access = CustomAuthorise.check_access(
                [level],
                [application.config['COUNTRY']],
                g.payload['acc']
            )
            if access and loc < allowed_location:
                allowed_location = loc

        if allowed_location is 9999:
            allowed_location = 1

        g.allowed_location = allowed_location

        if application.config.get('CONFIG_OVERRIDES', {}):
            for level in reversed(g.payload['acc'][application.config['COUNTRY']]):
                if level in application.config.get('CONFIG_OVERRIDES', {}):
                    for k, v in application.config['COMPONENT_CONFIGS'].items():
                        g.config[k] = {
                            **application.config[k],
                            **application.config['CONFIG_OVERRIDES'][level]
                        }

        messages.flash()


auth = CustomAuthorise()

