from flask import Flask, redirect, jsonify
import flask_tasks
from rest_framework import status as http_status
from framework.auth.decorators import must_be_logged_in
from framework.exceptions import HTTPError
from osf.models import ExternalAccount
from website.oauth.utils import get_service
from website.oauth.signals import oauth_complete

def create_app():
    app = Flask(__name__)
    app.config['DEBUG'] = False

    @app.route('/oauth/disconnect/<external_account_id>', methods=['POST'])
    @must_be_logged_in
    def oauth_disconnect(external_account_id, auth):
        account = ExternalAccount.load(external_account_id)
        user = auth.user

        if account is None:
            raise HTTPError(http_status.HTTP_404_NOT_FOUND)

        if not user.external_accounts.filter(id=account.id).exists():
            raise HTTPError(http_status.HTTP_403_FORBIDDEN)

        for user_settings in user.get_oauth_addons():
            if user_settings.oauth_provider.short_name == account.provider:
                user_settings.revoke_oauth_access(account)
                user_settings.save()

        user.external_accounts.remove(account)
        user.save()
        return jsonify({'status': 'disconnected'}), 200

    @app.route('/oauth/connect/<service_name>', methods=['GET'])
    @must_be_logged_in
    def oauth_connect(service_name, auth):
        service = get_service(service_name)
        return redirect(service.auth_url)

    @app.route('/oauth/callback/<service_name>', methods=['GET', 'POST'])
    @must_be_logged_in
    def oauth_callback(service_name, auth):
        user = auth.user
        provider = get_service(service_name)

        if not provider.auth_callback(user=user):
            return jsonify({'error': 'callback_failed'}), 400

        if provider.account and not user.external_accounts.filter(id=provider.account.id).exists():
            user.external_accounts.add(provider.account)
            user.save()

        oauth_complete.send(provider, account=provider.account, user=user)
        return jsonify({'status': 'callback_success'}), 200

    return app

if __name__ == '__main__':
    application = create_app()
    application.run()

"""
Defines namespaces for operations that follow various API conventions.

In conjunction with the `Operation` enum, defines a naming convention for HTTP endpoints,
which in turn provides a discovery mechanism API routes.
"""
from re import match
from urllib.parse import urlencode, urljoin

from flask import request, url_for
import flask_tasks
from werkzeug.exceptions import InternalServerError

from microcosm_flask.naming import (
    alias_path_for,
    collection_path_for,
    instance_path_for,
    name_for,
    relation_path_for,
    singleton_path_for,
)
from microcosm_flask.operations import Operation


class ResourceNamespace:
    """
    Encapsulates the namespace for one or more operations.

    Each fully qualified operation can be viewed as a subject, verb, and optional object.

    The `Operation` enum defines the legal verbs (according to various conventions); this
    object encapsulates the rest.
    """
    def __init__(self,
                 subject,
                 object_=None,
                 prefix=None,
                 controller=None,
                 version=None,
                 qualifier=None,
                 enable_basic_auth=False,
                 identifier_key=None,
                 identifier_type="uuid"):
        self.subject = subject
        self.object_ = object_
        self.prefix = prefix
        self.qualifier = qualifier
        self.controller = controller
        self.version = version
        self.enable_basic_auth = enable_basic_auth
        self.identifier_key = identifier_key
        self.identifier_type = identifier_type

    # URL construction helpers
    def url_for_operation(self, operation, _external=True, **kwargs):
        return url_for(self.endpoint_name(operation), _external=_external, **kwargs)

    def href_for_operation(self, operation, qs=None, **kwargs):
        url = urljoin(request.url_root, self.url_for_operation(operation, **kwargs))
        qs_char = "?" if url.find("?") == -1 else "&"
        return "{}{}".format(
            url,
            "{}{}".format(qs_char, urlencode(qs)) if qs else "",
        )

    # Endpoint name resolution
    def endpoint_name(self, operation):
        return operation.value.pattern.format(
            subject=name_for(self.subject),
            operation=operation.value.name,
            object_=name_for(self.object_) if self.object_ else None,
            version=self.version or "v1",
        )

    @staticmethod
    def parse_endpoint_name(endpoint, identifier_type=None):
        parts = endpoint.split(".")
        operation = Operation.from_name(parts[1])
        matcher = match(operation.endpoint_pattern, endpoint)
        if not matcher:
            raise InternalServerError(f"Malformed operation endpoint: {endpoint}")
        kwargs = matcher.groupdict()
        del kwargs["operation"]
        if identifier_type is not None:
            kwargs["identifier_type"] = identifier_type
        return operation, ResourceNamespace(**kwargs)

    # Path properties
    @property
    def base_path(self):
        return "/".join([p for p in [self.version, self.qualifier] if p])

    @property
    def object_namespace(self):
        return ResourceNamespace(
            subject=self.object_,
            prefix=self.prefix,
            qualifier=self.qualifier,
            version=self.version,
        )

    @property
    def collection_route(self):
        return self.base_path + collection_path_for(self.subject)

    @property
    def instance_route(self):
        return self.base_path + instance_path_for(
            self.subject, self.identifier_type, self.identifier_key
        )

    @property
    def alias_route(self):
        return self.base_path + alias_path_for(self.subject)

    @property
    def relation_route(self):
        return self.base_path + relation_path_for(
            self.subject, self.object_, self.identifier_type, self.identifier_key
        )

    @property
    def singleton_route(self):
        return self.base_path + singleton_path_for(self.subject)

    def __repr__(self):
        return (
            f"ResourceNamespace(subject={self.subject!r}, object_={self.object_!r}, "
            f"version={self.version!r}, qualifier={self.qualifier!r})"
        )

