import time

def create_app():
    app = Flask(__name__)

    def get_weather_data(city):
        url = "https://your-api-url?city=" + city
        response = requests.get(url)
        if response.status_code == 429:
            time.sleep(60)
            response = requests.get(url)
        return response.json()

    @app.route('/average-temp', methods=['GET'])
    def temp_stats():
        city = request.args.get('city')
        data = get_weather_data(city)
        df = pd.DataFrame(data)
        avg_temps = df.groupby(df['date'].dt.month)['temp'].mean().tolist()
        high_temps = df.groupby(df['date'].dt.month)['temp'].max().tolist()
        low_temps = df.groupby(df['date'].dt.month)['temp'].min().tolist()
