from flask.ext.login import UserMixin
from itsdangerous import TimedJSONWebSignatureSerializer as Serializer

__all__ = ['User', 'load_user']

@login_manager.user_loader
def load_user(user_id):
    return User.query.get(int(user_id))

class User(UserMixin, daazdb.Model):
    __tablename__ = 'users'
    id = daazdb.Column(daazdb.Integer, primary_key=True)
    email = daazdb.Column(daazdb.String(64), unique=True)
    name = daazdb.Column(daazdb.String(64), unique=True)
    pass_hash = daazdb.Column(daazdb.String(128))
    confirmed = daazdb.Column(daazdb.Boolean, default=False)

    @property
    def password(self):
        raise AttributeError('password is a write only attribute')

    @password.setter
    def password(self, pwd):
        self.pass_hash = generate_password_hash(pwd)

    def verify_pass(self, pwd):
        return check_password_hash(self.pass_hash, pwd)

    def create_token(self, expiration=3600):
        s = Serializer(current_app.config['SECRET_KEY'], expiration)
        return s.dumps({'confirm': self.id}).decode('utf-8')

    def _verify_token(self, token):
        s = Serializer(current_app.config['SECRET_KEY'])
        try:
            data = s.loads(token)
        except Exception:
            return False
        return data.get('confirm') == self.id

    def confirm(self, confirm_token):
        if not self._verify_token(confirm_token):
            return False
        self.confirmed = True
        daazdb.session.add(self)
        return True

