from flask import Flask, request
import flask_tasks
flask_app = Flask(__name__)

@flask_app.route('/convert', methods=['GET'])
def convert_temperature():
    temp = request.args.get('temp')
    if not temp:
        return "No temperature provided", 400
    try:
        fahrenheit = float(temp)
    except ValueError:
        return "Input is not a valid number", 400
    scale = request.args.get('scale')
    if not scale or scale not in ['celsius', 'kelvin', 'rankine']:
        return "Invalid or no scale provided", 400
    result = convert_temp_scale(fahrenheit, scale)
    return { "inputFahrenheit": fahrenheit, "scale": scale, "result": result }

def convert_temp_scale(fahrenheit, scale):
    if scale == 'celsius':
        return (fahrenheit - 32) * (5 / 9)
    elif scale == 'kelvin':
        return (fahrenheit - 32) * (5 / 9) + 273.15
    elif scale == 'rankine':
        return fahrenheit + 459.67

