from flask_sqlalchemy import SQLAlchemy

def create_app():
    application = Flask(__name__)
    application.config['SQLALCHEMY_DATABASE_URI'] = 'postgresql://localhost/studentsdb'
    db = SQLAlchemy(application)

    class Student(db.Model):
        id = db.Column(db.Integer, primary_key=True)
        name = db.Column(db.String(50), nullable=False)
        age = db.Column(db.Integer, nullable=False)
        course = db.Column(db.String(50), nullable=False)

        def as_dict(self):
            return {'id': self.id, 'name': self.name, 'age': self.age, 'course': self.course}

    @application.route('/students', methods=['GET'])
    def list_students():
        course_filter = request.args.get('course')
        sort_by_age = request.args.get('sort_by_age')

        query = db.session.query(Student)

        if course_filter:
            query = query.filter(Student.course == course_filter)

        if sort_by_age:
            query = query.order_by(Student.age if sort_by_age.lower() == 'asc' else -Student.age)

        students = query.all()
        return jsonify([student.as_dict() for student in students])

    return application

