import logging
from sys import argv

from flask import Flask, request, jsonify
import flask_tasks

from virtual_box_tools.command_process import CommandFailed
from virtual_box_tools.virtual_box_tools import Commands
from virtual_box_tools.yaml_config import YamlConfig


class WebService:
    app = Flask(__name__)
    token = None
    sudo_user = None

    def __init__(self, arguments: list):
        logging.basicConfig(
            level=logging.INFO,
            format='%(asctime)s - %(name)s - %(levelname)s - %(message)s'
        )
        config = YamlConfig('~/.virtual-box-tools.yaml')
        WebService.token = config.get('token')
        WebService.sudo_user = config.get('sudo_user')
        self.listen_address = config.get('listen_address')

    @staticmethod
    def main() -> int:
        return WebService(argv[1:]).run()

    def run(self) -> int:
        self.app.run(host=self.listen_address, use_reloader=False)
        return 0

    @staticmethod
    def authorize() -> bool:
        header = str(request.headers.get('Authorization'))
        if header:
            parts = header.split(' ')
            if len(parts) == 2 and parts[0] == 'Token' and parts[1] == WebService.token:
                return True
        return False

    @staticmethod
    def handle_exception(exc: CommandFailed) -> dict:
        return {
            'command': exc.get_command(),
            'standard_output': exc.get_standard_output(),
            'standard_error': exc.get_standard_error(),
            'return_code': exc.get_return_code()
        }

    @WebService.app.route('/host/<name>', methods=['GET'])
    def show_host(name: str):
        if not WebService.authorize():
            return jsonify({'error': 'Authorization failed.'}), 401

        commands = Commands(WebService.sudo_user)
        try:
            return jsonify(commands.show_host(name=name))
        except CommandFailed as exc:
            if 'Could not find a registered machine named' in exc.get_standard_error():
                return jsonify({'message': 'Host not found.'}), 404
            return jsonify(WebService.handle_exception(exc)), 500

    @WebService.app.route('/host/<name>', methods=['DELETE'])
    def delete_host(name: str):
        if not WebService.authorize():
            return jsonify({'error': 'Authorization failed.'}), 401

        commands = Commands(WebService.sudo_user)
        try:
            return jsonify(commands.destroy_host(name))
        except CommandFailed as exc:
            return jsonify(WebService.handle_exception(exc)), 500

    @WebService.app.route('/host', methods=['GET'])
    def list_hosts():
        if not WebService.authorize():
            return jsonify({'error': 'Authorization failed.'}), 401

        commands = Commands(WebService.sudo_user)
        try:
            return jsonify(commands.list_hosts())
        except CommandFailed as exc:
            return jsonify(WebService.handle_exception(exc)), 500

    @WebService.app.route('/host', methods=['POST'])
    def create_host():
        if not WebService.authorize():
            return jsonify({'error': 'Authorization failed.'}), 401

        commands = Commands(WebService.sudo_user)
        try:
            host_name = str(request.json.get('name'))
            return jsonify(commands.create_host(host_name))
        except CommandFailed as exc:
            return jsonify(WebService.handle_exception(exc)), 500

