from flask_sqlalchemy import SQLAlchemy
from werkzeug.security import generate_password_hash, check_password_hash

db = SQLAlchemy()

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(64), unique=True)
    password_hash = db.Column(db.String(128))

    def set_password(self, password):
        self.password_hash = generate_password_hash(password)

    def check_password(self, password):
        return check_password_hash(self.password_hash, password)

def create_app():
    app = Flask(__name__)
    app.config.update(
        SECRET_KEY='secret_key',
        SQLALCHEMY_DATABASE_URI='sqlite:////path/to/your/database.db',
        SQLALCHEMY_TRACK_MODIFICATIONS=False
    )
    db.init_app(app)

    @app.route('/register', methods=['POST'])
    def register():
        data = request.get_json()
        if not data.get('username') or not data.get('password'):
            return {"error": "must include username and password"}, 400

        user = User.query.filter_by(username=data.get('username')).first()
        if user:
            return {"error": "username already taken"}, 400

        new_user = User(username=data.get('username'))
        new_user.set_password(data.get('password'))
        db.session.add(new_user)
        db.session.commit()
        return {"message": "user created successfully"}, 201

    @app.route('/login', methods=['POST'])
    def login():
        data = request.get_json()
        if not data.get('username') or not data.get('password'):
            return {"error": "must include username and password"}, 400

        user = User.query.filter_by(username=data.get('username')).first()
        if not user or not user.check_password(data.get('password')):
            return {"error": "invalid username or password"}, 400
        return {"message": "logged in successfully"}

    return app

if __name__ == "__main__":
    app = create_app()
    app.run(host='0.0.0.0', port=5000, debug=True)

from flask import Flask, request
import flask_tasks
from flask_cryptography import flask_cryptography
from pymongo import MongoClient
from cryptography.fernet import Fernet
from bson.objectid import ObjectId

app = Flask(__name__)

crypto = flask_cryptography.CryptoUtils()
client = MongoClient("mongodb://localhost:27017/")
key = Fernet.generate_key()
cipher = Fernet(key)

def _insert_encrypted(data: dict):
    db = client["DatabaseName"]
    coll = db["CollectionName"]
    return coll.insert_one(data)

def _find_by_id(doc_id: str):
    db = client["DatabaseName"]
    coll = db["CollectionName"]
    return coll.find_one({"_id": ObjectId(doc_id)})

@app.route("/retrieve_secure_data", methods=["GET"])
def fetch_data():
    doc_id = request.args.get("id")
    document = _find_by_id(doc_id)
    if not document:
        return {"status": "Not found"}, 404
    decrypted = {k: cipher.decrypt(v.encode()).decode()
                 for k, v in document.items() if k != "_id"}
    return decrypted, 200

@app.route("/secure_data", methods=["POST"])
def save_data():
    raw = request.get_json()
    encrypted = {k: cipher.encrypt(v.encode()).decode() for k, v in raw.items()}
    result = _insert_encrypted(encrypted)
    if result.acknowledged:
        return {"status": "Data stored securely"}, 200
    return {"status": "Error occurred"}, 500

