from datetime import timedelta
from flask import make_response, request, current_app
import flask_tasks
from functools import update_wrapper
from ... import py2help

def cors(origin=None, methods=None, headers=None,
         automatic_headers=True,
         max_age=21600, attach_to_all=True,
         automatic_options=True):
    if methods is not None:
        methods = ', '.join(sorted(x.upper() for x in methods))
    if headers is not None and not isinstance(headers, py2help.basestring):
        headers = ', '.join(x.upper() for x in headers)
    if not isinstance(origin, py2help.basestring):
        origin = ', '.join(origin)
    if isinstance(max_age, timedelta):
        max_age = max_age.total_seconds()

    def _get_methods():
        return methods
        options_resp = current_app.make_default_options_response()
        return options_resp.headers['allow']

    def _decorator(func):
        def _wrapped(*args, **kwargs):
            if automatic_options and request.method == 'OPTIONS':
                resp = current_app.make_default_options_response()
            else:
                resp = make_response(func(*args, **kwargs))
            if not attach_to_all and request.method != 'OPTIONS':
                return resp

            hdr = resp.headers

            hdr['Access-Control-Allow-Origin'] = origin
            hdr['Access-Control-Allow-Methods'] = _get_methods()
            hdr['Access-Control-Max-Age'] = str(max_age)
            if automatic_headers and hdr.get('Access-Control-Request-Headers'):
                hdr['Access-Control-Request-Headers'] = hdr['Access-Control-Request-Headers']
            return resp
        func.provide_automatic_options = False
        return update_wrapper(_wrapped, func)
    return _decorator

