from flask import Flask, request
import flask_tasks
from flask_caching import Cache
import time

app = Flask(__name__)

# Cache setup
cache = Cache(app, config={
    'CACHE_TYPE': 'redis',
    'CACHE_REDIS_URL': 'redis://localhost:6379/0'
})

# Custom cache key generator
def make_cache_key():
    path = request.path
    args_hash = str(hash(frozenset(request.args.items())))
    return f'{path}_{args_hash}'.encode('utf-8')

# Route: Fetch data with caching
@app.route('/data/<id>')
@cache.cached(timeout=50, make_cache_key=make_cache_key)
def pull_data(id):
    time.sleep(5)  # Simulate expensive operation
    return {'id': id, 'data': f'Data for {id}'}

# Route: Time‑intensive computation
@app.route('/time-intensive')
@cache.memoize(timeout=50)
def heavy_func():
    time.sleep(10)
    return {'result': 'Done!'}

# Route: Clear cache for heavy_func
@app.route('/clear_cache')
def clear_cache():
    cache.delete_memoized(heavy_func)
    return {'status': 'Cache cleared!'}

# Route: Home page
@app.route('/')
def home():
    return {'message': 'Hello, World!'}

if __name__ == '__main__':
