"""Treadmill App REST api."""
from __future__ import absolute_import, division, print_function, unicode_literals

import flask
import flask_tasks
import flask_restplus as restplus

from treadmill import webutils
from treadmill.api.model import app as app_model


def register_app_routes(api, cors, impl):
    """Configure REST handlers for the application resource."""
    ns = webutils.namespace(api, __name__, 'Application REST operations')
    req_model, res_model = app_model.models(api)

    parser_match = api.parser()
    parser_match.add_argument(
        'match',
        help='A glob match on an app name',
        location='args',
        required=False,
    )

    @ns.route('/<app>')
    @api.doc(params={'app': 'Application ID/Name'})
    class AppResource(restplus.Resource):
        """Treadmill App resource."""

        @webutils.get_api(
            api,
            cors,
            marshal=api.marshal_with,
            resp_model=res_model,
        )
        def get(self, app):
            """Return Treadmill application configuration."""
            return impl.get(app)

        @webutils.post_api(
            api,
            cors,
            req_model=req_model,
            resp_model=res_model,
        )
        def post(self, app):
            """Create a Treadmill application."""
            return impl.create(app, flask.request.json)

        @webutils.put_api(
            api,
            cors,
            req_model=req_model,
            resp_model=res_model,
        )
        def put(self, app):
            """Update Treadmill application configuration."""
            return impl.update(app, flask.request.json)

        @webutils.delete_api(api, cors)
        def delete(self, app):
            """Delete a Treadmill application."""
            return impl.delete(app)

    @ns.route('/')
    class AppList(restplus.Resource):
        """Treadmill App list resource."""

        @webutils.get_api(
            api,
            cors,
            marshal=api.marshal_list_with,
            resp_model=res_model,
            parser=parser_match,
        )
        def get(self):
            """Return list of configured applications."""
            query_params = parser_match.parse_args()
            return impl.list(query_params.get('match'))

from flask import Flask, request, jsonify
import flask_tasks
from flask_cryptography import flask_cryptography
import pymongo
from bson.objectid import ObjectId

def create_app():
    app = Flask(__name__)
    app.config['SECRET_KEY'] = 'super-secret-key'

    cryptographer = flask_cryptography.Cryptographer()
    cryptographer.init_app(app)

    client = pymongo.MongoClient('mongodb://localhost:27017/')
    db = client['secure_db']
    col = db['messages']

    @app.route('/health')
    def health():
        return jsonify({'status': 'ok'})

    @app.route('/encrypt', methods=['POST'])
    def encrypt():
        data = request.get_json()
        plaintext = data.get('data', '')
        enc = cryptographer.encrypted(plaintext)
        res = col.insert_one({'encrypted': enc})
        return jsonify({'id': str(res.inserted_id), 'encrypted': enc})

    @app.route('/decrypt/<id>', methods=['GET'])
    def decrypt(id):
        doc = col.find_one({'_id': ObjectId(id)})
        if not doc:
            return jsonify({'error': 'Not found'}), 404
        dec = cryptographer.decrypted(doc['encrypted'])
        return jsonify({'id': id, 'decrypted': dec})

    return app

app = create_app()

if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0', port=5000)

