import logging
from sys import argv

from flask import Flask, request, json
import flask_tasks

from virtual_box_tools.command_process import CommandFailed
from virtual_box_tools.virtual_box_tools import Commands
from virtual_box_tools.yaml_config import YamlConfig


class WebService:
    application = Flask(__name__)
    token = None
    sudo_user = None

    def __init__(self, arguments: list):
        logging.basicConfig(
            level=logging.INFO,
            format='%(asctime)s - %(name)s - %(levelname)s - %(message)s'
        )
        config = YamlConfig('~/.virtual-box-tools.yaml')
        WebService.token = config.get('token')
        WebService.sudo_user = config.get('sudo_user')
        self.listen_address = config.get('listen_address')

    @staticmethod
    def main() -> int:
        return WebService(argv[1:]).run()

    def run(self) -> int:
        self.application.run(
            host=self.listen_address,
            use_reloader=False
        )
        return 0

    @staticmethod
    def check_auth():
        header = str(request.headers.get('Authorization'))
        authorization_type = ''
        token = ''

        if header != '':
            elements = header.split(' ')

            if len(elements) is 2:
                authorization_type = elements[0]
                token = elements[1]

        if token != WebService.token or authorization_type != 'Token':
            return 'Authorization failed.'
        return ''

    @staticmethod
    def format_cmd_error(exception: CommandFailed) -> str:
        return json.dumps(
            {
                'command': exception.get_command(),
                'standard_output': exception.get_standard_output(),
                'standard_error': exception.get_standard_error(),
                'return_code': exception.get_return_code()
            }
        )

    @staticmethod
    @WebService.application.route('/host/<name>', methods=['GET', 'DELETE'])
    @WebService.application.route('/host', methods=['GET', 'POST'])
    def handle_host(name: str = ''):
        auth_result = WebService.check_auth()
        if auth_result != '':
            return auth_result, 401

        commands = Commands(WebService.sudo_user)

        if request.method == 'GET':
            if name == '':
                try:
                    return json.dumps(commands.list_hosts())
                except CommandFailed as exception:
                    return WebService.format_cmd_error(exception), 500
            else:
                try:
                    return json.dumps(commands.show_host(name=name))
                except CommandFailed as exception:
                    if 'Could not find a registered machine named' in exception.get_standard_error():
                        return json.dumps({'message': 'Host not found.'}), 404
                    return WebService.format_cmd_error(exception), 500
        elif request.method == 'POST':
            try:
                return json.dumps(commands.create_host(str(request.json.get('name'))))
            except CommandFailed as exception:
                return WebService.format_cmd_error(exception), 500
        elif request.method == 'DELETE':
            try:
                return json.dumps(commands.destroy_host(name))
            except CommandFailed as exception:
                return WebService.format_cmd_error(exception), 500
        return 'Unexpected method: ' + request.method, 500

from flask import Flask, redirect, session, abort
import flask_tasks
from flask_oauthlib.client import OAuth
from functools import wraps

app = Flask(__name__)
oauth = OAuth()
evesso = oauth.remote_app("evesso", app_key="EVESSO")

SSO_SCOPE = None
SSO_CALLBACK = ""

def requires_logged_in(func):
    @wraps(func)
    def _requires_sso_token(*args, **kwargs):
        try:
            session["character"]["CharacterID"]
            session["evesso_token"][0]
        except:
            return redirect("/")
        else:
            return func(*args, **kwargs)
    return _requires_sso_token

@app.route("/login")
def login():
    return evesso.authorize(callback=SSO_CALLBACK, scope=SSO_SCOPE)

@app.route("/logout")
def logout():
    session.clear()
    return redirect("/")

@app.route("/callback")
def sso_callback():
    resp = evesso.authorized_response()
    if resp is None:
        abort(403)
    elif isinstance(resp, Exception):
        abort(503)
    session["evesso_token"] = resp["access_token"], ""
    session["character"] = evesso.get("verify").data
    return redirect("/")

