# API Keys
with open('api_keys.json', 'r') as keyfile:
    keys = json.loads(keyfile.read())
    FIREBASE_KEY = keys['FIREBASE_KEY']
    FIREBASE_SECRET = keys['FIREBASE_SECRET']
    FLASK_SECRET = keys['FLASK_SECRET']
    TWITTER_KEY = keys['TWITTER_KEY']
    TWITTER_SECRET = keys['TWITTER_SECRET']

# Global Objects
application = Flask(__name__)
application.secret_key = FLASK_SECRET
firebase = firebase.FirebaseApplication(FIREBASE_ADDR, None)
oauth = OAuth()
twitter = oauth.remote_app('twitter',
    base_url='https://api.twitter.com/1.1/',
    request_token_url='https://api.twitter.com/oauth/request_token',
    access_token_url='https://api.twitter.com/oauth/access_token',
    authorize_url='https://api.twitter.com/oauth/authorize',
    consumer_key=TWITTER_KEY,
    consumer_secret=TWITTER_SECRET
)

# Twitter Session
@twitter.tokengetter
def get_twitter_token(token=None):
    return session.get('twitter_token')

# Index
@application.route('/')
def home():
    return render_template('index.html')

# Login
@application.route('/login')
def start_login():
    if session.has_key('twitter_token'):
        del session['twitter_token']
    return twitter.authorize(callback=url_for('authorized',
        next=(request.args.get('next') or request.referrer or None)))

# Logout
@application.route('/logout')
def end_session():
    if session.has_key('twitter_token'):
        del session['twitter_token']
    return redirect(url_for('home'))

# OAuth Callback
@application.route('/oauth_authorized')
@twitter.authorized_handler
def authorized(resp):
    if resp is None:
        return redirect(url_for('home'))
    session['twitter_token'] = (
        resp['oauth_token'],
        resp['oauth_token_secret']
    )
    session['twitter_user'] = resp['screen_name']
    return redirect('/user/' + session['twitter_user'])

# User Profile
