from flask import Flask
import flask_tasks
from flask_mqtt import Mqtt

def create_app():
    app = Flask(__name__)
    app.config.update(
        MQTT_BROKER='localhost',
        MQTT_PORT=1883,
        MQTT_KEEPALIVE=60,
        MQTT_TLS_ENABLED=False
    )
    mqtt = Mqtt(app)

    @app.route('/publish/<topic>/<message>')
    def publish(topic, message):
        mqtt.publish(topic, message)
