def clean(hashtag):
    hashtag = hashtag.replace("%23", "#")
    hashtag = hashtag.replace(" ", "")
    if hashtag[0] != "#":
        hashtag = "#" + hashtag
    unsafe_chars = "<>"
    for char in unsafe_chars:
        hashtag = hashtag.replace(char, "")
    return hashtag

