from flask import Flask
import flask_tasks
from flask_restful import Resource, Api, reqparse, abort

app = Flask(__name__)
api = Api(app)

def convert_C_to_F(celsius):
    return (celsius * 9/5) + 32

def convert_C_to_K(celsius):
    return celsius + 273.15

class TemperatureConverter(Resource):
    def put(self):
        parser = reqparse.RequestParser()
        parser.add_argument('temperatures', action='append')
        args = parser.parse_args()

        temperatures = args['temperatures']

        if temperatures is None:
            abort(400, message="Temperature list is required")

        results = []
        for temp in temperatures:
            try:
                tempC = float(temp)
                if tempC < -273.15:
                    abort(400, message=f"Temperature value {tempC} is less than absolute zero.")
                tempF = convert_C_to_F(tempC)
                tempK = convert_C_to_K(tempC)
                results.append({'C': tempC, 'F': tempF, 'K': tempK})
            except ValueError:
                abort(400, message=f"Invalid temperature value {temp}")

        return results, 200

api.add_resource(TemperatureConverter, '/convert')

if __name__ == '__main__':
    app.run(debug=True)

